// ============================================================
// Paso 1: Obtener usuarios activos + items de MP en paralelo
// Combinar en pares (usuario × ítem) filtrados por config
// ============================================================

const API_BASE = 'http://172.17.0.1:8000';
const API_KEY  = 'mercadopublcio2025';
const MP_TICKET = 'B62A4372-14A4-4C86-8B06-FFF908CE0FBD';
const MP_BASE   = 'https://api2.mercadopublico.cl/v2/compra-agil';

// ---- 1. Obtener usuarios activos con su config ----
let usuarios = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${API_BASE}/admin/users/active`,
    headers: { 'X-API-Key': API_KEY }
  });
  usuarios = Array.isArray(resp) ? resp : [];
  console.log(`Usuarios activos con prompt: ${usuarios.length}`);
} catch(e) {
  console.error('Error obteniendo usuarios:', e.message);
  return [];
}

if (usuarios.length === 0) {
  console.log('Sin usuarios activos con prompt configurado');
  return [];
}

// ---- 2. Obtener items de Mercado Público ----
let allItems = [];
let pagina = 1;
let totalPaginas = 1;
let reintentos = 0;

while (pagina <= totalPaginas && reintentos < 5) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: MP_BASE,
      headers: { 'ticket': MP_TICKET },
      qs: {
        region: '10,11,9',
        estado: 'publicada',
        tamano_pagina: 50,
        numero_pagina: pagina
      }
    });

    if (resp.success !== 'OK' || !resp.payload?.items) break;

    totalPaginas = resp.payload.paginacion.total_paginas;
    allItems.push(...resp.payload.items);
    console.log(`Página MP ${pagina}/${totalPaginas} — ${resp.payload.items.length} items`);
    reintentos = 0;
    pagina++;
    if (pagina <= totalPaginas) await new Promise(r => setTimeout(r, 2000));
  } catch(err) {
    if (err.message?.includes('429') || err.response?.status === 429) {
      reintentos++;
      await new Promise(r => setTimeout(r, 5000));
      continue;
    }
    console.error('Error MP API:', err.message);
    break;
  }
}

const itemsConMonto = allItems.filter(i => (i.montos?.monto_disponible_clp ?? 0) > 0);
console.log(`Items MP con monto > 0: ${itemsConMonto.length}`);

if (itemsConMonto.length === 0) return [];

// ---- 3. Dedup global (por código, no repetir lo ya procesado) ----
const staticData = $getWorkflowStaticData('global');
const processedGlobal = staticData.processedCodes ?? {};
// processedGlobal = { 'USER_ID:CODIGO': true }

// ---- 4. Crear pares usuario × ítem filtrados ----
const pares = [];

for (const usuario of usuarios) {
  const regiones = new Set(usuario.regions || ['10', '11', '9']);
  const minClp   = usuario.min_amount_clp || 0;
  const maxClp   = usuario.max_amount_clp || null;

  for (const item of itemsConMonto) {
    const clave = `${usuario.user_id}:${item.codigo}`;
    if (processedGlobal[clave]) continue; // ya procesado

    // Filtro por región (comparar código numérico de región)
    const codigoRegion = String(item.institucion?.codigo_region ?? '');
    const nombreRegion = item.institucion?.nombre_region ?? '';
    const enRegion = regiones.has(codigoRegion) ||
      [...regiones].some(r => nombreRegion.toLowerCase().includes(r.toLowerCase()));
    if (regiones.size > 0 && !enRegion) continue;

    // Filtro por monto
    const monto = item.montos?.monto_disponible_clp ?? 0;
    if (monto < minClp) continue;
    if (maxClp && monto > maxClp) continue;

    const fechaCierre = item.fechas?.fecha_cierre
      ? item.fechas.fecha_cierre.split(' ')[0]
      : null;
    const montoStr = `$${Number(monto).toLocaleString('es-CL')} CLP`;
    const urlMP = `https://www.mercadopublico.cl/Procurement/Modules/RFB/DetailsAcquisition.aspx?idlicitacion=${item.codigo}`;

    pares.push({
      // Datos de usuario
      user_id:          usuario.user_id,
      user_email:       usuario.email,
      user_name:        usuario.name,
      company_name:     usuario.company_name,
      system_prompt:    usuario.system_prompt,
      min_score:        usuario.min_score,
      telegram_chat_id: usuario.telegram_chat_id,
      telegram_enabled: usuario.telegram_enabled,
      // Datos del ítem
      codigo:        item.codigo,
      nombre:        item.nombre ?? '',
      organismo:     item.institucion?.organismo_comprador ?? '',
      unidad_compra: item.institucion?.unidad_compra ?? '',
      region:        item.institucion?.nombre_region ?? '',
      monto_clp:     monto,
      fecha_cierre:  fechaCierre,
      url_mp:        urlMP,
      // Prompt para el AI Agent (datos del ítem)
      user_prompt: `Analiza esta Compra Ágil para ${usuario.company_name || usuario.user_email} y devuelve SOLO JSON:\n\nCÓDIGO: ${item.codigo}\nNOMBRE: ${item.nombre}\nORGANISMO: ${item.institucion?.organismo_comprador}\nUNIDAD: ${item.institucion?.unidad_compra}\nREGIÓN: ${item.institucion?.nombre_region}\nMONTO: ${montoStr}\nCIERRE: ${item.fechas?.fecha_cierre ?? 'No disponible'}\n\nJSON (sin markdown, sin texto extra):\n{\n  "score": <0-100>,\n  "viabilidad": "alta|media|baja",\n  "resumen": "<máx 2 líneas>",\n  "justificacion": "<máx 3 líneas>",\n  "riesgo": "<1 línea>",\n  "accion": "cotizar|investigar|ignorar",\n  "precio_sugerido_clp": <número o null>\n}`
    });
  }
}

console.log(`Pares usuario×ítem a procesar: ${pares.length}`);

if (pares.length === 0) {
  console.log('Sin pares nuevos para procesar');
  return [{ json: { message: 'Sin items nuevos', pares: 0 } }];
}

return pares.map(p => ({ json: p }));

// ============================================================
// Parsear output IA + guardar en PostgreSQL via FastAPI API
// Marcar ítem como procesado en static data
// ============================================================

const API_BASE = 'http://172.17.0.1:8000';
const API_KEY  = 'mercadopublcio2025';

const allInputs = $input.all();
const contextos = $('Fetch MP + Usuarios').all();
const results   = [];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedCodes) staticData.processedCodes = {};

for (let i = 0; i < allInputs.length; i++) {
  const agentOutput = allInputs[i].json.output ?? allInputs[i].json.text ?? JSON.stringify(allInputs[i].json);
  const ctx = contextos[i]?.json;
  if (!ctx || !ctx.codigo) continue;

  // Parsear JSON del agente
  let scoring;
  try {
    const clean = String(agentOutput).replace(/```json|```/g, '').trim();
    const match = clean.match(/\{[\s\S]*\}/);
    scoring = JSON.parse(match ? match[0] : clean);
  } catch(e) {
    scoring = {
      score: 0, viabilidad: 'baja',
      resumen: 'Error al parsear IA',
      justificacion: String(agentOutput).substring(0, 200),
      riesgo: 'Error de parsing',
      accion: 'ignorar',
      precio_sugerido_clp: null
    };
  }

  const score = Number(scoring.score) || 0;

  // Marcar como procesado siempre (evita reprocesar en próxima ejecución)
  const clave = `${ctx.user_id}:${ctx.codigo}`;
  staticData.processedCodes[clave] = true;

  // Descartar si score muy bajo
  if (score < 40) {
    console.log(`⬇️ Score bajo (${score}) para ${ctx.codigo} / ${ctx.user_email}`);
    continue;
  }

  // Guardar en PostgreSQL via FastAPI
  let opportunityId = null;
  let created = false;
  try {
    const saveResp = await this.helpers.httpRequest({
      method: 'POST',
      url: `${API_BASE}/admin/save-opportunity`,
      headers: { 'X-API-Key': API_KEY, 'Content-Type': 'application/json' },
      body: {
        user_id:             ctx.user_id,
        codigo:              ctx.codigo,
        nombre:              ctx.nombre,
        organismo:           ctx.organismo,
        region:              ctx.region,
        monto_clp:           ctx.monto_clp,
        fecha_cierre:        ctx.fecha_cierre,
        url_mp:              ctx.url_mp,
        score,
        viabilidad:          scoring.viabilidad ?? 'baja',
        accion:              scoring.accion ?? 'ignorar',
        resumen:             (scoring.resumen ?? '').substring(0, 2000),
        justificacion:       (scoring.justificacion ?? '').substring(0, 2000),
        riesgo:              (scoring.riesgo ?? '').substring(0, 500),
        precio_sugerido_clp: scoring.precio_sugerido_clp ?? null
      }
    });
    opportunityId = saveResp.opportunity_id;
    created       = saveResp.created;
    console.log(`${created ? '✅ NUEVO' : '⏭️ YA EXISTE'} ${ctx.codigo} / ${ctx.user_email} — score ${score}`);
  } catch(e) {
    console.error(`❌ Error guardando ${ctx.codigo}:`, e.message);
    continue;
  }

  results.push({ json: {
    opportunity_id:   opportunityId,
    created,
    user_id:          ctx.user_id,
    user_email:       ctx.user_email,
    company_name:     ctx.company_name,
    telegram_chat_id: ctx.telegram_chat_id,
    telegram_enabled: ctx.telegram_enabled,
    min_score:        ctx.min_score,
    codigo:           ctx.codigo,
    nombre:           ctx.nombre,
    organismo:        ctx.organismo,
    region:           ctx.region,
    monto_clp:        ctx.monto_clp,
    fecha_cierre:     ctx.fecha_cierre,
    url_mp:           ctx.url_mp,
    score,
    viabilidad:       scoring.viabilidad ?? 'baja',
    accion:           scoring.accion ?? 'ignorar',
    resumen:          scoring.resumen ?? '',
    justificacion:    scoring.justificacion ?? '',
    riesgo:           scoring.riesgo ?? ''
  }});

  await new Promise(r => setTimeout(r, 300));
}

console.log(`Guardados: ${results.length}`);
if (results.length === 0) return [{ json: { message: 'Sin oportunidades nuevas' } }];
return results;
